import "fmt"

// A struct groups related fields into one type.
type Book struct {
	Title, Author string
	Pages         int
	Read          bool
}

func main() {
	// Fields by name; the missing ones take their zero value.
	novel := Book{Title: "Emma", Author: "Jane Austen", Pages: 474}
	tale := Book{"Matilda", "Roald Dahl", 240, true} // or all, in order

	novel.Read = true // the dot reads and changes fields
	fmt.Println(novel)
	fmt.Printf("%+v\n", tale) // %+v also shows the field names

	// Assigning a struct copies it.
	gift := tale
	gift.Title = "Matilda (gift)"
	fmt.Println(tale.Title, "|", gift.Title)

	// A slice of structs: a small bookshelf.
	shelf := []Book{novel, tale, {Title: "Dracula", Author: "Bram Stoker", Pages: 418}}
	total := 0
	for i := 0; i < len(shelf); i++ {
		fmt.Printf("%-8s %-12s %4d %v\n", shelf[i].Title, shelf[i].Author, shelf[i].Pages, shelf[i].Read)
		total += shelf[i].Pages
	}
	fmt.Println("Total pages:", total)
}

package main

import "fmt"

type Room struct {
	Name          string
	Width, Length float64
}

// A method has a receiver before its name: (r Room).
func (r Room) Area() float64 {
	return r.Width * r.Length
}

// A pointer receiver (*Room) can change the original room.
func (r *Room) Extend(meters float64) {
	r.Length += meters
}

// String() decides how fmt prints a Room.
func (r Room) String() string {
	return fmt.Sprintf("%-8s %.1f x %.1f m", r.Name, r.Width, r.Length)
}

func main() {
	flat := []Room{{"Kitchen", 3, 4.5}, {"Bedroom", 3.5, 4}, {"Bath", 2, 2.5}}
	flat[2].Extend(1) // Go passes &flat[2] for us
	total := 0.0
	for i := 0; i < len(flat); i++ {
		fmt.Printf("%v -> %5.2f m2\n", flat[i], flat[i].Area())
		total += flat[i].Area()
	}
	fmt.Printf("Whole flat: %.2f m2\n", total)
}

package main

import "fmt"

type Player struct {
	Name  string
	Score int
}

// Gets a copy of the number: the change is lost.
func bonusCopy(score int) { score += 50 }

// Gets the address: *score is the original variable.
func bonus(score *int) { *score += 50 }

// With a pointer to a struct, p.Score is enough (no * needed).
func levelUp(p *Player) { p.Score += 100 }

func main() {
	score := 120
	ptr := &score // & gives the address of the variable
	fmt.Println("score:", score, "| *ptr:", *ptr)
	*ptr = 150 // * reaches the value behind the address
	fmt.Println("After *ptr = 150:", score)
	bonusCopy(score)
	fmt.Println("After bonusCopy:", score)
	bonus(&score)
	fmt.Println("After bonus:", score)
	ana := &Player{Name: "Ana", Score: 10}
	levelUp(ana)
	fmt.Println(ana.Name, "now has", ana.Score, "points")
	var nobody *Player // a pointer starts as nil
	fmt.Println("nobody == nil:", nobody == nil)
}

package main

import (
	"fmt"
	"strconv"
	"strings"
)

func main() {
	line := "  milk, eggs ,bread,  olive oil  "

	// Split cuts at each comma; TrimSpace removes the spaces around.
	parts := strings.Split(line, ",")
	for i := 0; i < len(parts); i++ {
		parts[i] = strings.TrimSpace(parts[i])
	}
	fmt.Printf("%d items: %q\n", len(parts), parts)
	fmt.Println(strings.Join(parts, " | "))
	fmt.Println("Upper:", strings.ToUpper(parts[0]), "| has eggs:", strings.Contains(line, "eggs"))
	fmt.Println("Replace:", strings.Replace(parts[3], "olive", "sunflower", 1), "| commas:", strings.Count(line, ","))
	fmt.Println(strings.Repeat("-", 24))

	// strconv turns text into numbers and numbers into text.
	units, err := strconv.Atoi("12")
	fmt.Println("12 units x 2 =", units*2, "error:", err)
	price, _ := strconv.ParseFloat("2.75", 64)
	fmt.Println("Price x 2 =", price*2)
	if _, err := strconv.Atoi("twelve"); err != nil {
		fmt.Println("Error:", err)
	}
	label := "Pack of " + strconv.Itoa(units) + ": " + strconv.FormatFloat(price*float64(units), 'f', 2, 64)
	fmt.Println(label)
}

